<?php
$config = require __DIR__ . '/config.php';
$pdo = new PDO("mysql:host={$config['db_host']};dbname={$config['db_name']};charset=utf8mb4", $config['db_user'], $config['db_pass'], [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]);
$rows = $pdo->query('SELECT * FROM orders ORDER BY created_at DESC LIMIT 100')->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Panel zamówień</title><style>body{font-family:Arial,sans-serif;background:#f5f0e6;margin:0;padding:24px}table{width:100%;border-collapse:collapse;background:#fff}th,td{padding:10px;border:1px solid #ddd;font-size:14px;vertical-align:top}th{background:#324b25;color:#fff}h1{margin:0 0 16px}</style></head><body><h1>Panel zamówień</h1><table><tr><th>ID</th><th>Klient</th><th>Kontakt</th><th>Produkt</th><th>Ilość</th><th>Adres</th><th>Status</th><th>Data</th></tr><?php foreach($rows as $r): ?><tr><td><?= htmlspecialchars($r['id']) ?></td><td><?= htmlspecialchars($r['name']) ?></td><td><?= htmlspecialchars(($r['email'] ?? '').' / '.($r['phone'] ?? '')) ?></td><td><?= htmlspecialchars($r['product']) ?></td><td><?= htmlspecialchars($r['qty']) ?></td><td><?= htmlspecialchars($r['address']) ?></td><td><?= htmlspecialchars($r['status']) ?></td><td><?= htmlspecialchars($r['created_at']) ?></td></tr><?php endforeach; ?></table></body></html>
